  BabyRecipe(id: 'be8_01', title: 'Buharda havuç çubukları', age: '8+', category: 'Sebze', ingredient: 'havuç', vegetable: 'havuç', ingredients: ['1 havuç'], steps: ['Havucu soyup serçe parmak uzunluğunda çubuklar kesin.', 'Buharda 15–18 dakika, parmakla kolayca ezilene kadar pişirin.', 'Ilıtın.', 'Bebeğin önüne 2–3 çubuk koyun.'], tips: ['Parmak yiyecekleri bebeğin avucuna sığacak, serçe parmak uzunluğunda ve dişsiz damakla ezilebilecek yumuşaklıkta olmalı; yemek boyunca bebeğin yanında kalın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_02', title: 'Fırında tatlı patates dilimleri', age: '8+', category: 'Sebze', ingredient: 'tatlı patates', vegetable: 'tatlı patates', ingredients: ['1 tatlı patates', '1 tatlı kaşığı zeytinyağı'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Tatlı patatesi soyup kalın parmak dilimler kesin.', 'Zeytinyağıyla harmanlayıp yağlı kâğıda dizin.', '25–30 dakika, içi yumuşayana kadar pişirin.', 'Ilıtıp servis edin.'], tips: ['Parmak yiyecekleri bebeğin avucuna sığacak, serçe parmak uzunluğunda ve dişsiz damakla ezilebilecek yumuşaklıkta olmalı; yemek boyunca bebeğin yanında kalın.'], storage: 'Buzdolabında 48 saat.'),
