  BabyRecipe(id: 'be8_10', title: 'Haşlanmış armut dilimleri', age: '8+', category: 'Meyve', ingredient: 'armut', vegetable: 'armut', ingredients: ['1 armut'], steps: ['Armudu soyup kalın dilimler kesin.', 'Buharda 5–6 dakika yumuşatın.', 'Ilıtın.', 'Bebeğin önüne koyun.'], tips: ['Parmak yiyecekleri bebeğin avucuna sığacak, serçe parmak uzunluğunda ve dişsiz damakla ezilebilecek yumuşaklıkta olmalı; yemek boyunca bebeğin yanında kalın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_11', title: 'Ev yapımı tuzsuz bebek peyniri (lor)', age: '8+', category: 'Süt ürünü', ingredient: 'süt', vegetable: 'süt', ingredients: ['1 litre tam yağlı pastörize süt', '2 yemek kaşığı limon suyu'], steps: ['Sütü kaynamaya yakın ısıtın (yaklaşık 85 °C).', 'Limon suyunu ekleyip ateşi kapatın, 10 dakika bekletin.', 'Kesilen sütü tülbentten süzün.', '30 dakika asılı bırakıp suyunu akıtın.', 'Tuz eklemeden buzdolabında saklayın.'], tips: ['Süt pişirildiği için 8 aydan itibaren peynir olarak verilebilir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_12', title: 'Fırında yumurtalı sebze muffin (bebek)', age: '9+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'brokoli', ingredients: ['2 yumurta', '3 yemek kaşığı ince doğranmış brokoli', '2 yemek kaşığı rendelenmiş havuç', '1 yemek kaşığı tuzsuz lor'], steps: ['Fırını 180 °C\'ye ısıtın.', 'Yumurtayı çırpıp sebzeler ve lorla karıştırın.', 'Mini muffin kalıplarına paylaştırın.', '18 dakika, ortası tamamen pişene kadar pişirin.', 'Ilıtıp ikiye bölerek servis edin.'], tips: ['Kahvaltıda ve dışarıda pratik bir öğündür.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_13', title: 'Mercimek köftesi (bebek, acısız)', age: '10+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'soğan', ingredients: ['Yarım su bardağı kırmızı mercimek', 'Yarım su bardağı ince bulgur', '1 yemek kaşığı zeytinyağı', '1 küçük soğan (ince kıyılmış)', 'Yarım demet maydanoz (ince kıyılmış)'], steps: ['Mercimeği 2 su bardağı suyla dağılana kadar pişirin.', 'Ocaktan alıp bulguru ekleyin, kapağı kapalı 20 dakika bekletin.', 'Soğanı zeytinyağında yumuşatıp ekleyin, maydanozu katın.', 'Yoğurup küçük parmak köfteler yapın.'], tips: ['Salça, pul biber ve tuz eklemeyin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_14', title: 'Tavuklu sebzeli küp köfte', age: '9+', category: 'Et', ingredient: 'tavuk', vegetable: 'kabak', ingredients: ['100 g tavuk kıyma', '2 yemek kaşığı rendelenmiş kabak (suyu sıkılmış)', '1 yemek kaşığı ince yulaf'], steps: ['Tüm malzemeyi yoğurun.', 'Küçük köfteler yapın.', 'Yağlı kâğıtta 190 °C fırında 18 dakika pişirin.', 'İçinin tamamen piştiğini kontrol edip ılıtın.'], tips: ['Tavuk iyi pişmeli; kesince pembe görünmemeli.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bey_01', title: 'Ev yoğurdu (bebek için)', age: '6+', category: 'Yoğurt', ingredient: 'süt', vegetable: 'süt', ingredients: ['1 litre tam yağlı pastörize süt', '1 yemek kaşığı tam yağlı yoğurt (maya)'], steps: ['Sütü kaynatıp 45 °C’ye (serçe parmağı 10 saniye tutulabilecek sıcaklık) soğutun.', 'Mayayı biraz sütle açıp ekleyin, karıştırın.', 'Kabın üzerini örtüp sıcak yerde 6–8 saat bekletin.', 'Kıvam alınca buzdolabına kaldırın.'], tips: ['Yoğurt 6 aydan itibaren tamamlayıcı besin olarak verilebilir; şeker eklemeyin.'], storage: 'Buzdolabında kapalı kapta 3 gün.'),
