  BabyRecipe(id: 'bey_03', title: 'Yoğurtlu yulaf (gece bekletmeli, bebek)', age: '9+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'elma', ingredients: ['3 yemek kaşığı ince yulaf', '4 yemek kaşığı ev yoğurdu', '2 yemek kaşığı rendelenmiş elma'], steps: ['Yulaf, yoğurt ve elmayı karıştırın.', 'Kapalı kapta buzdolabında bir gece bekletin.', 'Sabah oda sıcaklığına getirin.', 'Kaşıkla servis edin.'], tips: ['Yulaf yumuşayarak kolay yenir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bey_04', title: 'Yoğurt çorbası (bebek, tuzsuz)', age: '9+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'pirinç', ingredients: ['2 yemek kaşığı pirinç', '4 yemek kaşığı ev yoğurdu', '1 yumurta sarısı', '1 su bardağı içme suyu', '1 çay kaşığı tereyağı'], steps: ['Pirinci suyla 20 dakika pişirin.', 'Yoğurt ve yumurta sarısını çırpıp sıcak çorbadan ekleyerek ılıştırın.', 'Tencereye ekleyip sürekli karıştırarak bir taşım kaynatın.', 'Tereyağı ekleyip ılık servis edin.'], tips: ['Tuz ve nane eklemeyin.'], storage: 'Buzdolabında 48 saat.'),
