  BabyRecipe(id: 'bey_06', title: 'Lorlu armut ezmesi', age: '8+', category: 'Süt ürünü', ingredient: 'lor peyniri', vegetable: 'armut', ingredients: ['2 yemek kaşığı tuzsuz lor', 'Yarım haşlanmış armut'], steps: ['Armudu ezin.', 'Lorla karıştırın.', 'Kıvamı koyuysa biraz anne sütü ekleyin.', 'Hemen servis edin.'], tips: ['Tuzsuz lor protein ve kalsiyum sağlar.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bey_07', title: 'Sütlü irmik lapası (12+ ay)', age: '12+', category: 'Süt ürünü', ingredient: 'süt', vegetable: 'irmik', ingredients: ['1 su bardağı süt', '1 yemek kaşığı irmik', 'Yarım muz'], steps: ['Sütü ısıtın, irmiği yağmur gibi serperek ekleyin.', 'Sürekli karıştırarak 5 dakika pişirin.', 'Ezilmiş muzu ekleyin.', 'Ilıtıp servis edin.'], tips: ['12 aydan önce inek sütü yerine anne sütü veya mamayla yapılmalı; şeker eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bey_08', title: 'Sütlaç (şekersiz, çocuk)', age: '12+', category: 'Süt ürünü', ingredient: 'süt', vegetable: 'pirinç', ingredients: ['2 yemek kaşığı pirinç', '2 su bardağı süt', '1 tatlı kaşığı pirinç unu', 'Yarım muz veya 2 hurma (çekirdeksiz, ezilmiş)'], steps: ['Pirinci yarım su bardağı suyla yumuşayana kadar pişirin.', 'Sütü ekleyip kaynatın.', 'Pirinç ununu biraz sütle açıp ekleyin, 10 dakika karıştırarak pişirin.', 'Muz veya hurma ezmesiyle tatlandırıp kaselere alın.'], tips: ['Tatlandırıcı olarak şeker yerine meyve kullanın.'], storage: 'Buzdolabında kapalı kapta 3 gün.'),
