  BabyRecipe(id: 'bei_01', title: 'Ayran (çocuk, tuzsuz)', age: '12+', category: 'İçecek', ingredient: 'yoğurt', vegetable: 'yoğurt', ingredients: ['3 yemek kaşığı ev yoğurdu', 'Yarım su bardağı içme suyu'], steps: ['Yoğurdu suyla çırpın.', 'Köpürtün.', 'Bardağa alıp hemen servis edin.', 'Tuz eklemeyin.'], tips: ['Tuzsuz ayran yemekle iyi gider.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
