  BabyRecipe(id: 'bei_04', title: 'Ev yapımı elma suyu (seyreltilmiş)', age: '12+', category: 'İçecek', ingredient: 'elma', vegetable: 'elma', ingredients: ['1 elma', '1 su bardağı içme suyu'], steps: ['Elmayı soyup doğrayın.', 'Suyla 10 dakika pişirin.', 'Süzüp soğutun.', 'Günde en fazla yarım su bardağı verin.'], tips: ['Meyve suyu yerine bütün meyve tercih edilmeli; günlük miktarı sınırlı tutun.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bei_05', title: 'Kayısı kompostosu (şekersiz)', age: '12+', category: 'İçecek', ingredient: 'kuru kayısı', vegetable: 'kayısı', ingredients: ['6 kuru kayısı (kükürtsüz)', '2 su bardağı içme suyu'], steps: ['Kayısıları yıkayıp 2 saat suda bekletin.', 'Aynı suyla 15 dakika pişirin.', 'Soğutup suyu ve doğranmış kayısıyı servis edin.', 'Kayısı tanelerini küçük doğrayın.'], tips: ['Kükürtsüz (koyu renkli) kayısı seçin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bei_06', title: 'Yulaf sütü (ev yapımı, 12+ ay)', age: '12+', category: 'İçecek', ingredient: 'yulaf', vegetable: 'yulaf', ingredients: ['Yarım su bardağı yulaf', '3 su bardağı soğuk içme suyu'], steps: ['Yulafı 15 dakika suda bekletip süzün.', 'Yeni suyla 30 saniye blenderdan geçirin.', 'Tülbentten süzün.', 'Buzdolabında saklayın.'], tips: ['Bitkisel sütler inek sütünün yerini tutmaz; ana içecek olarak verilmemeli.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bei_07', title: 'Ihlamur (çocuk, şekersiz)', age: '24+', category: 'İçecek', ingredient: 'ıhlamur', vegetable: 'ıhlamur', ingredients: ['1 tatlı kaşığı ıhlamur', '1 su bardağı su'], steps: ['Suyu kaynatın.', 'Ihlamuru ekleyip ocağı kapatın.', '5 dakika demleyip süzün.', 'Ilıtıp yarım çay bardağı verin.'], tips: ['Bitki çaylarını küçük çocuklara sık ve fazla vermeyin; ilaç kullanıyorsa doktora danışın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bef_01', title: 'Tuzsuz menemen (çocuk)', age: '12+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'domates', ingredients: ['1 yumurta', '1 domates (kabuksuz)', 'Çeyrek yeşil biber', '1 çay kaşığı tereyağı'], steps: ['Biberi tereyağında yumuşatın.', 'Rendelenmiş domatesi 5 dakika pişirin.', 'Yumurtayı ekleyip tamamen pişene kadar karıştırın.', 'Ilıtıp ekmekle servis edin.'], tips: ['Yumurta tamamen pişmeli; tuz eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bef_02', title: 'Kabaklı domatesli bulgur pilavı (çocuk)', age: '12+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'domates', ingredients: ['Yarım su bardağı pilavlık bulgur', '1 domates', 'Yarım kabak', '1 çay kaşığı tereyağı', '1 su bardağı su'], steps: ['Kabağı küçük doğrayıp tereyağında 2 dakika çevirin.', 'Rendelenmiş domatesi ekleyin.', 'Bulgur ve suyu ekleyip suyunu çekene kadar pişirin.', '10 dakika demlendirip servis edin.'], tips: ['Tuz eklemeden aileye ayrıca tuzlanabilir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bef_03', title: 'Fırında tavuk ve sebze (çocuk)', age: '12+', category: 'Et', ingredient: 'tavuk', vegetable: 'patates', ingredients: ['1 tavuk but (kemiksiz)', '1 patates', '1 havuç', '1 tatlı kaşığı zeytinyağı', '1 çay kaşığı kekik'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Tavuk ve sebzeleri küçük doğrayıp yağ ve kekikle harmanlayın.', 'Kapalı fırın kabında 35 dakika pişirin.', 'Tavuğun iyice piştiğini kontrol edip ılıtın.'], tips: ['Kapalı pişirmek etin yumuşak kalmasını sağlar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bef_04', title: 'Mini sebzeli pizza (çocuk)', age: '18+', category: 'Fırın', ingredient: 'tam buğday lavaş', vegetable: 'domates', ingredients: ['1 tam buğday lavaş', '2 yemek kaşığı rendelenmiş domates', '2 yemek kaşığı rendelenmiş kaşar', '1 yemek kaşığı ince doğranmış biber ve mantar'], steps: ['Fırını 200 °C\'ye ısıtın.', 'Lavaşı bardakla yuvarlak kesin.', 'Domates, sebze ve kaşarı koyun.', '8 dakika pişirip ılıtın.'], tips: ['Sucuk ve salam gibi işlenmiş etleri eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bef_05', title: 'Ev yapımı tam buğday krakeri', age: '18+', category: 'Fırın', ingredient: 'tam buğday unu', vegetable: 'susam', ingredients: ['1 su bardağı tam buğday unu', '2 yemek kaşığı zeytinyağı', '4 yemek kaşığı su', '1 tatlı kaşığı susam'], steps: ['Fırını 180 °C\'ye ısıtın.', 'Malzemeleri yoğurup ince açın.', 'Küçük kareler kesip çatalla delin.', '15 dakika pişirin.'], tips: ['Tuzsuz krakerler atıştırmalık için uygundur.'], storage: 'Buzdolabında kapalı kapta 3 gün.'),
